      <CardSurface tone="full" padding="none" className="h-[760px] w-[356px] max-w-full overflow-hidden rounded-3xl border border-border-button-default p-2">
        <AgentCreator value={agent} onChange={setAgent} />
      </CardSurface>
    </div>
  );
}

