"use client";
import { Button } from "../../base/buttons/button";
import { CloseButton } from "../../base/buttons/close-button";
import { InputBase, TextField } from "../../base/input/input";
import { TextareaField } from "../../base/textarea/textarea";
import { VerticalScroll } from "../../base/scroll-area/vertical-scroll";
import { RiGlobalLine, RiNotification3Line, RiVolumeUpLine, RiPlayMiniFill } from "@remixicon/react";
import { useState } from "react";
import { AgentEmotionWheel, AgentShapeSelector } from "./agent-appearance-controls";
import { AgentColorPicker } from "./agent-color-picker";
import { Select, SelectItem } from "../../base/select/select";
import { Switch } from "../../base/switch/switch";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "../../base/segmented-control/segmented-control";
import { AgentAvatar, type AgentAvatarProps } from "./agent-avatar";
import { cardSurfaceClasses } from "../charts/card-surface";
import { cx } from "../../utils/cx";
import { agentVoicePreviewText, resolveAgentVoice, useAgentVoices } from "./agent-voices";
export interface AgentConfiguration {
  name: string;
  label: string;
  description: string;
  color: string;
  emotionColor?: string;
  shape: NonNullable<AgentAvatarProps["shape"]>;
  language: string;
  notifications: boolean;
  voice: string;
  speed: string;
  emotion?: number;
}
export const DEFAULT_AGENT_CONFIGURATION: AgentConfiguration = {
  name: "Security agent",
  label: "Security",
  description: "A careful second pair of eyes for permissions, privacy, and application security.",
  color: "#a4dfe0",
  emotionColor: "#b3e4e5",
  shape: "shield",
  language: "auto",
  notifications: true,
  voice: "Alice",
  speed: "1",
};
export interface AgentCreatorProps {
  value?: AgentConfiguration;
  onChange?: (value: AgentConfiguration) => void;
  className?: string;
  onClose?: () => void;
}
export function AgentCreator({ value, onChange, className, onClose }: AgentCreatorProps = {}) {
  const [local, setLocal] = useState(DEFAULT_AGENT_CONFIGURATION);
  const v = value ?? local;
  const voices = useAgentVoices(v.language);
  const voice = resolveAgentVoice(v.voice, voices);
  const voiceKey = v.voice === "off" ? "off" : voice?.voiceURI ?? "system";
  const change = (p: Partial<AgentConfiguration>) => {
    const next = { ...v, ...p };
    setLocal(next);
    onChange?.(next);
  };
  return (
    <section
      aria-label="Agent editor"
      className={cx("flex h-full min-h-0 flex-col bg-background-full ps-1 pe-2", className)}
    >
      <header className="relative flex h-8 shrink-0 items-start justify-center pt-4">
        <h2 className="max-w-[260px] truncate text-body-medium text-text-primary">{v.name}</h2>
        {onClose && (
          <CloseButton
            aria-label="Close agent editor"
            onClick={onClose}
            className="absolute end-0 top-3.5"
          />
        )}
      </header>
      <VerticalScroll aria-label="Agent appearance and details" scrollClassName="pb-4">
        <div className="relative h-[360px] overflow-hidden">
          <div className="pointer-events-none absolute top-[30px] left-1/2 z-10 -translate-x-1/2">
            <AgentEmotionWheel
              color={v.emotionColor ?? v.color}
              value={v.emotion ?? 0}
              onChange={(emotion) => change({ emotion })}
            />
          </div>
          <AgentAvatar
            color={v.color}
            shape={v.shape}
            emotion={v.emotion ?? 0}
            className="pointer-events-none absolute top-[83px] left-1/2 size-[162px] -translate-x-1/2"
          />
          <div className="absolute inset-x-0 bottom-0">
            <AgentShapeSelector
              color={v.color}
              value={v.shape}
              onChange={(shape) => change({ shape })}
            />
          </div>
        </div>
        <div className="mt-[15px] flex justify-center">
          <AgentColorPicker value={v.color} onChange={(color, emotionColor) => change({ color, emotionColor })} />
        </div>
        <div
          className={cx(cardSurfaceClasses({ padding: "none" }), "mt-[15px] overflow-hidden ps-3")}
        >
          {(["name", "label", "description"] as const).map((key) => (
            <label
              key={key}
              className={cx(
                "grid min-h-[52px] grid-cols-[96px_minmax(0,1fr)] items-center border-b border-border-button-default dark:border-border-button-default/35 pe-2.5 text-body-regular text-text-primary last:border-0",
                key === "description" && "min-h-[82px] items-start py-2.5",
              )}
            >
              <span className={cx("capitalize", key === "description" && "pt-1")}>{key}</span>
              {key === "description" ? (
                <TextareaField
                  aria-label={`Agent ${key}`}
                  value={v[key]}
                  onChange={(e) => change({ [key]: e.target.value })}
                  rows={2}
                  autoResize
                  maxLength={500}
                  placeholder="Details for the agent"
                  className="resize-none"
                  fieldClassName="min-h-[62px] px-1.5 py-2"
                />
              ) : (
                <TextField size="small" aria-label={`Agent ${key}`} value={v[key]}
                  onChange={(value) => change({ [key]: value })}>
                  <InputBase aria-label={`Agent ${key}`} maxLength={key === "name" ? 48 : 60}
                    placeholder={key === "name" ? "Agent name" : "Manager, marketing, painter"}
                    fieldClassName="rounded-2lg bg-background-tertiary-default" className="text-left" />
                </TextField>
              )}
            </label>
          ))}
        </div>
        <div className={cx(cardSurfaceClasses({ padding: "none" }), "mt-4 flex flex-col px-3")}>
          <div className="flex min-h-14 items-center justify-between gap-3 border-b border-separator-border py-3">
            <span className="flex items-center gap-2 text-body-medium text-text-primary">
              <RiGlobalLine className="size-5 text-foreground-icon-secondary" />
              Language
            </span>
            <Select
              aria-label="Agent language"
              popoverClassName="w-48"
              size="sm"
              selectedKey={v.language}
              onSelectionChange={(key) => change({ language: String(key) })}
            >
              {[
                ["auto", "Auto-detect"],
                ["en", "English"],
                ["tr", "Turkish"],
                ["es", "Spanish"],
                ["fr", "French"],
                ["de", "German"],
                ["ja", "Japanese"],
                ["pt", "Portuguese"],
              ].map(([id, label]) => (
                <SelectItem key={id} id={id}>
                  {label}
                </SelectItem>
              ))}
            </Select>
          </div>
          <div className="flex items-center gap-3 py-3">
            <RiNotification3Line className="size-5 shrink-0 text-foreground-icon-secondary" />
            <div className="flex min-w-0 flex-1 flex-col gap-1">
              <p className="text-body-medium text-text-primary">Notifications</p>
              <p className="text-caption-1-regular text-text-secondary">
                Show a notice when a reply is ready.
              </p>
            </div>
            <Switch
              aria-label="Notify when this agent finishes"
              size="sm"
              isSelected={v.notifications}
              onChange={(notifications) => change({ notifications })}
            />
          </div>
        </div>
        <div
          className={cx(
            cardSurfaceClasses({ padding: "none" }),
            "mt-3 flex flex-col gap-3 p-3 pt-2",
          )}
        >
          <div className="flex items-center justify-between gap-3">
            <span className="flex items-center gap-2 text-body-medium text-text-primary">
              <RiVolumeUpLine className="size-5 text-foreground-icon-secondary" />
              Voice
            </span>
            <div className="flex min-w-0 items-center gap-1">
              {v.voice !== "off" && <Button
                variant="ghost"
                size="small"
                iconOnly
                leadingIcon={RiPlayMiniFill}
                aria-label="Preview voice"
                className="size-8 bg-transparent p-0 text-text-secondary hover:bg-background-tertiary-default hover:text-text-primary active:bg-background-tertiary-hover active:text-text-primary"
                onClick={() => {
                  if (typeof speechSynthesis !== "undefined") {
                    speechSynthesis.cancel();
                    const speech = new SpeechSynthesisUtterance(agentVoicePreviewText(v.language));
                    speech.rate = Number(v.speed);
                    speech.lang = voice?.lang ?? (v.language === "auto" ? "en-US" : v.language);
                    if (voice) speech.voice = voice;
                    speechSynthesis.speak(speech);
                  }
                }}
              />}
              <Select
                aria-label="Agent voice"
                popoverClassName="w-60"
                size="sm"
                selectedKey={voiceKey}
                onSelectionChange={(key) => change({ voice: String(key) })}
              >
                <SelectItem id="off">Off</SelectItem>
                <SelectItem id="system">System voice</SelectItem>
                {voices.map((voice) => (
                  <SelectItem key={voice.voiceURI} id={voice.voiceURI}>{voice.name}</SelectItem>
                ))}
              </Select>
            </div>
          </div>
          <span className="text-caption-1-regular text-text-secondary">Playback speed</span>
          <SegmentedControl
            selectedKeys={[v.speed]}
            onSelectionChange={(keys) => change({ speed: String([...keys][0]) })}
            aria-label="Playback speed"
          >
            {["0.75", "1", "1.25", "1.5"].map((speed) => (
              <SegmentedControlItem key={speed} id={speed}>
                {speed}×
              </SegmentedControlItem>
            ))}
          </SegmentedControl>
        </div>
      </VerticalScroll>
    </section>
  );
}
